// src/interfaces/IAssetForwarder.sol

/// @title Interface for handler contracts that support deposits and deposit executions.
/// @author Router Protocol.
interface IAssetForwarder {
    event FundsDeposited(
        uint256 partnerId,
        uint256 amount,
        bytes32 destChainIdBytes,
        uint256 destAmount,
        uint256 depositId,
        address srcToken,
        address depositor,
        bytes recipient,
        bytes destToken
    );

    event FundsDepositedWithMessage(
        uint256 partnerId,
        uint256 amount,
        bytes32 destChainIdBytes,
        uint256 destAmount,
        uint256 depositId,
        address srcToken,
        bytes recipient,
        address depositor,
        bytes destToken,
        bytes message
    );
    event FundsPaid(bytes32 messageHash, address forwarder, uint256 nonce);

    event DepositInfoUpdate(
        address srcToken,
        uint256 feeAmount,
        uint256 depositId,
        uint256 eventNonce,
        bool initiatewithdrawal,
        address depositor
    );

    event FundsPaidWithMessage(
        bytes32 messageHash,
        address forwarder,
        uint256 nonce,
        bool execFlag,
        bytes execData
    );

    struct RelayData {
        uint256 amount;
        bytes32 srcChainId;
        uint256 depositId;
        address destToken;
        address recipient;
    }

    struct RelayDataMessage {
        uint256 amount;
        bytes32 srcChainId;
        uint256 depositId;
        address destToken;
        address recipient;
        bytes message;
    }

    struct DepositData {
        uint256 partnerId;
        uint256 amount;
        uint256 destAmount;
        address srcToken;
        address refundRecipient;
        bytes32 destChainIdBytes;
    }

    function iDeposit(
        DepositData memory depositData,
        bytes memory destToken,
        bytes memory recipient
    ) external payable;

    function iDepositInfoUpdate(
        address srcToken,
        uint256 feeAmount,
        uint256 depositId,
        bool initiatewithdrawal
    ) external payable;

    function iDepositMessage(
        DepositData memory depositData,
        bytes memory destToken,
        bytes memory recipient,
        bytes memory message
    ) external payable;

    function iRelay(RelayData memory relayData) external payable;

    function iRelayMessage(RelayDataMessage memory relayData) external payable;
}

// src/interfaces/IDexSpan.sol

contract IDexSpanConsts {
    // flags = FLAG_DISABLE_UNISWAP + FLAG_DISABLE_BANCOR + ...
    uint256 internal constant FLAG_DISABLE_UNISWAP = 0x400;
    uint256 internal constant FLAG_DISABLE_SPLIT_RECALCULATION = 0x800000000000;
    uint256 internal constant FLAG_DISABLE_ALL_SPLIT_SOURCES = 0x20000000;
    uint256 internal constant FLAG_DISABLE_UNISWAP_V2_ALL = 0x400;
    uint256 internal constant FLAG_DISABLE_EMPTY = 0x100000000000;

    uint256 internal constant FLAG_DISABLE_DFYN = 0x800;
    uint256 internal constant FLAG_DISABLE_PANCAKESWAP = 0x80;
    uint256 internal constant FLAG_DISABLE_QUICKSWAP = 0x40000000000;
    uint256 internal constant FLAG_DISABLE_SUSHISWAP = 0x1000000;
    uint256 internal constant FLAG_DISABLE_ONEINCH = 0x100000;
}

abstract contract IDexSpan is IDexSpanConsts {
    struct SwapPayload {
        uint256[] flags;
        uint256 minToAmount;
        address[] tokens;
        bytes[] dataTx;
    }

    struct SwapParams {
        address[] tokens;
        uint256 amount;
        uint256 minReturn;
        uint256[] flags;
        bytes[] dataTx;
        bool isWrapper;
        address recipient;
        bytes destToken;
    }

    function transferOwnership(address _newOwner) external virtual;

    function claimOwnership() external virtual;

    function setAssetForwarder(address _forwarder) external virtual;

    function setAssetBridge(address _assetBridge) external virtual;

    function setFlagToFactoryAddress(
        uint256 _flagCode,
        address _factoryAddress
    ) external virtual;

    function setFactorySetter(address _factorySetter) external virtual;

    function setWNativeAddresses(
        address _native,
        address _wrappedNative
    ) external virtual;

    function handleMessage(
        address _tokenSent,
        uint256 _amount,
        bytes memory message
    ) external virtual;

    function swapInSameChain(
        address[] memory tokens,
        uint256 amount,
        uint256 minReturn,
        uint256[] memory flags,
        bytes[] memory dataTx,
        bool isWrapper,
        address recipient,
        uint256 widgetID
    ) external virtual payable;

    function swapMultiWithRecipient(
        address[] memory tokens,
        uint256 amount,
        uint256 minReturn,
        uint256[] memory flags,
        bytes[] memory dataTx,
        bool isWrapper,
        address recipient
    ) public payable virtual returns (uint256 returnAmount);

    function swapAndDeposit(
        uint256 partnerId,
        bytes32 destChainIdBytes,
        bytes calldata recipient,
        uint8 depositType,
        uint256 feeAmount,
        bytes memory message,
        SwapParams memory swapData,
        address refundRecipient
    ) public payable virtual;
}

// src/AssetForwarderSwapper.sol

contract AssetForwarderSwapper {
    address public immutable forwarder;
    IDexSpan public immutable dexspan;
    address constant NATIVE_TOKEN = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    struct SwapParams {
        address[] tokens;
        uint256 amount;
        uint256 minReturn;
        uint256[] flags;
        bytes[] dataTx;
        bool isWrapper;
        address recipient;
    }
    constructor(address _forwarder, address _dexspan) {
        forwarder = _forwarder;
        dexspan = IDexSpan(_dexspan);
    }

    function iRelaySwap(
        SwapParams memory _params,
        IAssetForwarder.RelayData memory _relayData
    ) external payable {
        SafeTransferLib.safeTransferFrom(
            _params.tokens[0],
            msg.sender,
            address(dexspan),
            _params.amount
        );

        dexspan.swapInSameChain{value: msg.value}(
            _params.tokens,
            _params.amount,
            _params.minReturn,
            _params.flags,
            _params.dataTx,
            _params.isWrapper,
            _params.recipient,
            1
        );
        if (_relayData.destToken != NATIVE_TOKEN) {
            SafeTransferLib.safeApprove(
                _relayData.destToken,
                forwarder,
                _relayData.amount
            );
        }
        IAssetForwarder(forwarder).iRelay{
            value: _relayData.destToken == NATIVE_TOKEN ? _relayData.amount : 0
        }(_relayData);
        if (_relayData.destToken != NATIVE_TOKEN) {
            SafeTransferLib.safeTransfer(
                _relayData.destToken,
                _relayData.recipient,
                SafeTransferLib.balanceOf(_relayData.destToken, address(this))
            );
        } else {
            SafeTransferLib.safeTransferAllETH(_relayData.recipient);
        }
    }

    function iRelayMessageSwap(
        SwapParams memory _params,
        IAssetForwarder.RelayDataMessage memory _relayData
    ) external payable {
        SafeTransferLib.safeTransferFrom(
            _params.tokens[0],
            msg.sender,
            address(dexspan),
            _params.amount
        );

        dexspan.swapInSameChain{value: msg.value}(
            _params.tokens,
            _params.amount,
            _params.minReturn,
            _params.flags,
            _params.dataTx,
            _params.isWrapper,
            _params.recipient,
            1
        );
        if (_relayData.destToken != NATIVE_TOKEN) {
            SafeTransferLib.safeApprove(
                _relayData.destToken,
                forwarder,
                _relayData.amount
            );
        }
        IAssetForwarder(forwarder).iRelayMessage{
            value: _relayData.destToken == NATIVE_TOKEN ? _relayData.amount : 0
        }(_relayData);
        if (_relayData.destToken != NATIVE_TOKEN) {
            SafeTransferLib.safeTransfer(
                _relayData.destToken,
                _relayData.recipient,
                SafeTransferLib.balanceOf(_relayData.destToken, address(this))
            );
        } else {
            SafeTransferLib.safeTransferAllETH(_relayData.recipient);
        }
    }

    receive() external payable {}
}
